//! Builds patches for staging, unstaging and discarding parts of a file's diff.
//!
//! The diff is regenerated by the backend instead of being taken from the frontend, and each
//! selected hunk is checked against the header the frontend saw, so a file that changed in the
//! meantime is never patched wrongly. Lines are kept as bytes, so files in any encoding and with
//! any line endings survive unchanged.

use serde::Deserialize;

use crate::git::GitResult;

/// The selected hunks no longer match the diff (the file changed since it was shown).
pub const STALE: &str = "The file changed since its diff was shown. Try again on the updated diff.";

/// One hunk of a single-file diff: its `@@` header and its body lines, without line breaks.
#[derive(Debug, Clone, PartialEq)]
pub struct Hunk {
    pub header: String,
    pub old_start: u32,
    pub new_start: u32,
    /// Lines starting with ' ', '+', '-' or '\' (a "No newline at end of file" marker).
    pub lines: Vec<Vec<u8>>,
}

/// A single-file diff split into its file header (`diff --git`, `---`, `+++`, modes) and hunks.
#[derive(Debug, Clone, PartialEq)]
pub struct FilePatch {
    pub header: Vec<Vec<u8>>,
    pub hunks: Vec<Hunk>,
}

/// What the frontend selected in one hunk: the whole hunk, or some of its body lines.
#[derive(Deserialize, Debug, Clone)]
#[serde(rename_all = "camelCase")]
pub struct HunkSelection {
    pub index: usize,
    /// The hunk's `@@` line as shown, to detect a diff that changed in the meantime.
    pub header: String,
    /// Indexes into the hunk's body lines; only '+' and '-' lines count. None selects every line.
    pub lines: Option<Vec<usize>>,
}

/// Parses `@@ -a[,b] +c[,d] @@` into the two start lines.
fn parse_hunk_header(line: &str) -> Option<(u32, u32)> {
    let rest = line.strip_prefix("@@ -")?;
    let (old, rest) = rest.split_once(" +")?;
    let (new, _) = rest.split_once(" @@")?;
    let start = |range: &str| range.split(',').next()?.parse().ok();
    Some((start(old)?, start(new)?))
}

/// Splits the diff of one file. Refuses binary diffs, renames and copies, and diffs of several files.
pub fn parse(diff: &[u8]) -> GitResult<FilePatch> {
    let mut lines: Vec<&[u8]> = diff.split(|&b| b == b'\n').collect();
    if lines.last().is_some_and(|l| l.is_empty()) {
        lines.pop();
    }
    let mut header = Vec::new();
    let mut hunks: Vec<Hunk> = Vec::new();
    for line in lines {
        if line.starts_with(b"@@") {
            let text = String::from_utf8_lossy(line).into_owned();
            let (old_start, new_start) =
                parse_hunk_header(&text).ok_or_else(|| format!("Unexpected hunk header: {text}"))?;
            hunks.push(Hunk {
                header: text,
                old_start,
                new_start,
                lines: Vec::new(),
            });
        } else if let Some(hunk) = hunks.last_mut() {
            if line.starts_with(b"diff ") {
                return Err("The diff covers more than one file".into());
            }
            hunk.lines.push(line.to_vec());
        } else {
            if line.starts_with(b"Binary files") || line.starts_with(b"GIT binary patch") {
                return Err("Parts of binary files can't be staged".into());
            }
            if line.starts_with(b"rename from") || line.starts_with(b"copy from") {
                return Err("Parts of renamed files can't be staged".into());
            }
            if line.starts_with(b"diff ") && !header.is_empty() {
                return Err("The diff covers more than one file".into());
            }
            header.push(line.to_vec());
        }
    }
    Ok(FilePatch { header, hunks })
}

/// Number of lines in the diff as the frontend counts them: hunk headers and body lines.
pub fn shown_lines(patch: &FilePatch) -> usize {
    patch.hunks.iter().map(|h| 1 + h.lines.len()).sum()
}

/// A hunk of the patch being built.
struct OutHunk<'a> {
    old_start: u32,
    old_count: u32,
    new_start: u32,
    new_count: u32,
    /// What follows the line ranges in the original header, e.g. a function name.
    context: &'a str,
    body: Vec<Vec<u8>>,
}

/// Builds a patch with only the selected changes, to apply with `git apply --recount`.
///
/// Applied forward (staging, `reverse` false) the patch goes onto the old side of the diff, so
/// unselected additions are left out and unselected deletions become context. Applied in reverse
/// (unstaging and discarding) it goes onto the new side, so unselected additions become context
/// and unselected deletions are left out. Hunks without selected changes are dropped. Returns
/// None when nothing is selected.
pub fn build(patch: &FilePatch, selection: &[HunkSelection], reverse: bool) -> GitResult<Option<Vec<u8>>> {
    let mut selection = selection.to_vec();
    selection.sort_by_key(|s| s.index);
    selection.dedup_by_key(|s| s.index);

    let mut out_hunks: Vec<OutHunk> = Vec::new();
    for sel in &selection {
        let hunk = patch.hunks.get(sel.index).ok_or(STALE)?;
        if hunk.header != sel.header {
            return Err(STALE.into());
        }
        let selected = |i: usize| sel.lines.as_ref().is_none_or(|lines| lines.contains(&i));
        let (mut old_count, mut new_count, mut changes) = (0u32, 0u32, 0usize);
        let mut body: Vec<Vec<u8>> = Vec::new();
        // Whether the previous body line made it into the patch, for "\ No newline" markers.
        let mut kept_previous = false;
        for (i, line) in hunk.lines.iter().enumerate() {
            let (kind, rest) = match line.split_first() {
                Some((&k, rest)) => (k, rest),
                // An empty line stands for an empty context line.
                None => (b' ', &[][..]),
            };
            let as_context = |rest: &[u8]| [b" ", rest].concat();
            let emitted = match kind {
                b'+' if selected(i) => Some(line.clone()),
                b'-' if selected(i) => Some(line.clone()),
                b'+' if reverse => Some(as_context(rest)),
                b'-' if !reverse => Some(as_context(rest)),
                b'+' | b'-' => None,
                b'\\' => {
                    if kept_previous {
                        body.push(line.clone());
                    }
                    continue;
                }
                _ => Some(as_context(rest)),
            };
            kept_previous = emitted.is_some();
            if let Some(l) = emitted {
                match l[0] {
                    b'+' => {
                        new_count += 1;
                        changes += 1;
                    }
                    b'-' => {
                        old_count += 1;
                        changes += 1;
                    }
                    _ => {
                        old_count += 1;
                        new_count += 1;
                    }
                }
                body.push(l);
            }
        }
        if changes == 0 {
            continue;
        }
        // A range of zero lines starts at the line before it; one with lines starts at 1 at least.
        let old_start = if old_count > 0 {
            hunk.old_start.max(1)
        } else {
            hunk.old_start
        };
        let new_start = if new_count > 0 {
            hunk.new_start.max(1)
        } else {
            hunk.new_start
        };
        let context = hunk.header.split_once(" @@").map_or("", |(_, c)| c);
        out_hunks.push(OutHunk {
            old_start,
            old_count,
            new_start,
            new_count,
            context,
            body,
        });
    }
    if out_hunks.is_empty() {
        return Ok(None);
    }

    // A new file that keeps some lines on the old side (as context) is no longer a creation, and a
    // deleted file that keeps some on the new side no longer a deletion: describe both as edits,
    // or git refuses the patch.
    let old_lines: u32 = out_hunks.iter().map(|h| h.old_count).sum();
    let new_lines: u32 = out_hunks.iter().map(|h| h.new_count).sum();
    let is_new = patch.header.iter().any(|l| l.starts_with(b"new file mode"));
    let is_deleted = patch.header.iter().any(|l| l.starts_with(b"deleted file mode"));
    let header = if (is_new && old_lines > 0) || (is_deleted && new_lines > 0) {
        as_modification(&patch.header)
    } else {
        patch.header.clone()
    };

    let mut out = Vec::new();
    for line in header {
        out.extend_from_slice(&line);
        out.push(b'\n');
    }
    for h in out_hunks {
        let header = format!(
            "@@ -{},{} +{},{} @@{}\n",
            h.old_start, h.old_count, h.new_start, h.new_count, h.context
        );
        out.extend_from_slice(header.as_bytes());
        for line in h.body {
            out.extend_from_slice(&line);
            out.push(b'\n');
        }
    }
    Ok(Some(out))
}

/// Turns the header of a file creation or deletion into one of an edit of the file.
fn as_modification(header: &[Vec<u8>]) -> Vec<Vec<u8>> {
    let find = |prefix: &[u8]| {
        header
            .iter()
            .find(|l| l.starts_with(prefix) && !l.ends_with(b"/dev/null"))
            .map(|l| l[prefix.len()..].to_vec())
    };
    // The other side's path with its "a/" or "b/" prefix swapped, inside quotes or not.
    let swap = |path: Vec<u8>, from: u8, to: u8| -> Vec<u8> {
        let mut path = path;
        let at = usize::from(path.first() == Some(&b'"'));
        if path.get(at) == Some(&from) && path.get(at + 1) == Some(&b'/') {
            path[at] = to;
        }
        path
    };
    let new_path = find(b"+++ ");
    let old_path = find(b"--- ");
    header
        .iter()
        .filter(|l| {
            !(l.starts_with(b"new file mode") || l.starts_with(b"deleted file mode") || l.starts_with(b"index "))
        })
        .map(|l| {
            if l.as_slice() == b"--- /dev/null"
                && let Some(p) = &new_path
            {
                [b"--- ".as_slice(), &swap(p.clone(), b'b', b'a')].concat()
            } else if l.as_slice() == b"+++ /dev/null"
                && let Some(p) = &old_path
            {
                [b"+++ ".as_slice(), &swap(p.clone(), b'a', b'b')].concat()
            } else {
                l.clone()
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    const MODIFIED: &str = "diff --git a/f.txt b/f.txt
index 1111111..2222222 100644
--- a/f.txt
+++ b/f.txt
@@ -1,4 +1,4 @@ fn main
 one
-two
+TWO
 three
 four
@@ -10,2 +10,4 @@
 ten
+eleven
+twelve
 thirteen
";

    fn sel(index: usize, header: &str, lines: Option<Vec<usize>>) -> HunkSelection {
        HunkSelection {
            index,
            header: header.into(),
            lines,
        }
    }

    fn built(diff: &str, selection: &[HunkSelection], reverse: bool) -> String {
        let patch = parse(diff.as_bytes()).unwrap();
        String::from_utf8(build(&patch, selection, reverse).unwrap().unwrap()).unwrap()
    }

    #[test]
    fn parses_header_and_hunks() {
        let patch = parse(MODIFIED.as_bytes()).unwrap();
        assert_eq!(patch.header.len(), 4);
        assert_eq!(patch.hunks.len(), 2);
        assert_eq!(patch.hunks[0].header, "@@ -1,4 +1,4 @@ fn main");
        assert_eq!((patch.hunks[1].old_start, patch.hunks[1].new_start), (10, 10));
        assert_eq!(patch.hunks[1].lines.len(), 4);
        assert_eq!(shown_lines(&patch), 11);
    }

    #[test]
    fn refuses_binary_renamed_and_multi_file_diffs() {
        let binary = "diff --git a/i.png b/i.png\nindex 1..2 100644\nBinary files a/i.png and b/i.png differ\n";
        assert!(parse(binary.as_bytes()).is_err());
        let renamed = "diff --git a/a b/b\nsimilarity index 90%\nrename from a\nrename to b\n@@ -1 +1 @@\n-x\n+y\n";
        assert!(parse(renamed.as_bytes()).is_err());
        let two = format!("{MODIFIED}{MODIFIED}");
        assert!(parse(two.as_bytes()).is_err());
    }

    #[test]
    fn keeps_a_whole_hunk_as_it_is() {
        let out = built(MODIFIED, &[sel(1, "@@ -10,2 +10,4 @@", None)], false);
        assert_eq!(
            out,
            "diff --git a/f.txt b/f.txt\nindex 1111111..2222222 100644\n--- a/f.txt\n+++ b/f.txt\n\
             @@ -10,2 +10,4 @@\n ten\n+eleven\n+twelve\n thirteen\n"
        );
    }

    #[test]
    fn refuses_a_stale_selection() {
        let patch = parse(MODIFIED.as_bytes()).unwrap();
        assert_eq!(
            build(&patch, &[sel(0, "@@ -1,3 +1,3 @@", None)], false),
            Err(STALE.into())
        );
        assert_eq!(
            build(&patch, &[sel(5, "@@ -1,4 +1,4 @@ fn main", None)], false),
            Err(STALE.into())
        );
    }

    #[test]
    fn forward_leaves_out_unselected_additions_and_keeps_unselected_deletions() {
        // Stage only "+TWO": "-two" stays as context.
        let out = built(MODIFIED, &[sel(0, "@@ -1,4 +1,4 @@ fn main", Some(vec![2]))], false);
        assert!(
            out.ends_with("@@ -1,4 +1,5 @@ fn main\n one\n two\n+TWO\n three\n four\n"),
            "{out}"
        );
    }

    #[test]
    fn reverse_keeps_unselected_additions_and_leaves_out_unselected_deletions() {
        // Discard only "+TWO": "-two" is dropped, nothing else changes.
        let out = built(MODIFIED, &[sel(0, "@@ -1,4 +1,4 @@ fn main", Some(vec![2]))], true);
        assert!(
            out.ends_with("@@ -1,3 +1,4 @@ fn main\n one\n+TWO\n three\n four\n"),
            "{out}"
        );
        // Discard only "+twelve" of the second hunk: "+eleven" becomes context.
        let out = built(MODIFIED, &[sel(1, "@@ -10,2 +10,4 @@", Some(vec![2]))], true);
        assert!(
            out.ends_with("@@ -10,3 +10,4 @@\n ten\n eleven\n+twelve\n thirteen\n"),
            "{out}"
        );
    }

    #[test]
    fn combines_hunks_and_drops_those_without_selected_changes() {
        let out = built(
            MODIFIED,
            &[
                sel(1, "@@ -10,2 +10,4 @@", Some(vec![1])),
                sel(0, "@@ -1,4 +1,4 @@ fn main", Some(vec![0, 3])),
            ],
            false,
        );
        assert_eq!(out.matches("@@ -").count(), 1);
        assert!(out.ends_with("@@ -10,2 +10,3 @@\n ten\n+eleven\n thirteen\n"), "{out}");
        let patch = parse(MODIFIED.as_bytes()).unwrap();
        assert_eq!(
            build(&patch, &[sel(0, "@@ -1,4 +1,4 @@ fn main", Some(vec![0]))], false),
            Ok(None)
        );
    }

    #[test]
    fn keeps_no_newline_markers_with_their_line() {
        let diff = "diff --git a/f b/f\n--- a/f\n+++ b/f\n@@ -1,2 +1,2 @@\n a\n-b\n\\ No newline at end of file\n+c\n\\ No newline at end of file\n";
        let header = "@@ -1,2 +1,2 @@";
        let out = built(diff, &[sel(0, header, Some(vec![3]))], false);
        assert!(
            out.ends_with(" a\n b\n\\ No newline at end of file\n+c\n\\ No newline at end of file\n"),
            "{out}"
        );
        let out = built(diff, &[sel(0, header, Some(vec![1]))], false);
        assert!(out.ends_with(" a\n-b\n\\ No newline at end of file\n"), "{out}");
    }

    #[test]
    fn turns_a_partial_new_file_into_an_edit() {
        let diff = "diff --git a/n.txt b/n.txt\nnew file mode 100644\nindex 0000000..1234567\n--- /dev/null\n+++ b/n.txt\n@@ -0,0 +1,3 @@\n+x\n+y\n+z\n";
        let header = "@@ -0,0 +1,3 @@";
        // Staging some lines needs no context: still a creation.
        let out = built(diff, &[sel(0, header, Some(vec![0, 2]))], false);
        assert!(
            out.contains("new file mode") && out.ends_with("@@ -0,0 +1,2 @@\n+x\n+z\n"),
            "{out}"
        );
        // Discarding one keeps the others as context: an edit of the file.
        let out = built(diff, &[sel(0, header, Some(vec![1]))], true);
        assert_eq!(
            out,
            "diff --git a/n.txt b/n.txt\n--- a/n.txt\n+++ b/n.txt\n@@ -1,2 +1,3 @@\n x\n+y\n z\n"
        );
    }

    #[test]
    fn turns_a_partial_deletion_into_an_edit() {
        let diff = "diff --git a/d.txt b/d.txt\ndeleted file mode 100644\nindex 1234567..0000000\n--- a/d.txt\n+++ /dev/null\n@@ -1,2 +0,0 @@\n-x\n-y\n";
        let out = built(diff, &[sel(0, "@@ -1,2 +0,0 @@", Some(vec![0]))], false);
        assert_eq!(
            out,
            "diff --git a/d.txt b/d.txt\n--- a/d.txt\n+++ b/d.txt\n@@ -1,2 +1,1 @@\n-x\n y\n"
        );
    }

    #[test]
    fn swaps_prefixes_of_quoted_paths() {
        let header = vec![b"--- /dev/null".to_vec(), b"+++ \"b/t\\tab\"".to_vec()];
        assert_eq!(as_modification(&header)[0], b"--- \"a/t\\tab\"".to_vec());
    }

    #[test]
    fn keeps_bytes_and_carriage_returns() {
        let diff = b"diff --git a/w b/w\n--- a/w\n+++ b/w\n@@ -1 +1 @@\n-caf\xe9\r\n+caf\xc3\xa9\r\n";
        let patch = parse(diff).unwrap();
        let out = build(&patch, &[sel(0, "@@ -1 +1 @@", None)], false).unwrap().unwrap();
        let expected = b"diff --git a/w b/w\n--- a/w\n+++ b/w\n@@ -1,1 +1,1 @@\n-caf\xe9\r\n+caf\xc3\xa9\r\n";
        assert_eq!(out, expected.to_vec());
    }
}
